// Node.js: TCP server and client using the 'net' module
const net = require('net');

// ── TCP Server ────────────────────────────────────────────────
const server = net.createServer((socket) => {
  console.log('Client connected:', socket.remoteAddress);

  socket.on('data', (data) => {
    const msg = data.toString().trim();
    console.log('Received:', msg);
    // Echo back with transformation
    socket.write(`Echo: ${msg.toUpperCase()}\n`);
  });

  socket.on('end', () => console.log('Client disconnected'));
  socket.on('error', (err) => console.error('Socket error:', err.message));
});

server.listen(9000, '127.0.0.1', () => {
  console.log('TCP server listening on port 9000');

  // ── TCP Client (connects after server is ready) ───────────────
  const client = net.createConnection({ port: 9000, host: '127.0.0.1' }, () => {
    console.log('Connected to server');
    client.write('hello tcp\n');
  });

  client.on('data', (data) => {
    console.log('Server replied:', data.toString().trim());
    client.end();   // Send FIN — triggers four-way teardown
    server.close(); // Stop accepting new connections
  });

  client.on('error', (err) => console.error('Client error:', err.message));
});

// Output:
// TCP server listening on port 9000
// Connected to server
// Client connected: 127.0.0.1
// Received: hello tcp
// Server replied: Echo: HELLO TCP
// Client disconnected

// ── TCP vs UDP Quick Reference ────────────────────────────────
//
// Feature            │ TCP                    │ UDP
// ───────────────────┼────────────────────────┼──────────────────
// Connection         │ Required (3-way HS)    │ None
// Ordering           │ Guaranteed             │ Not guaranteed
// Reliability        │ Retransmits lost segs  │ No retransmit
// Flow control       │ Yes (receive window)   │ No
// Congestion control │ Yes (CUBIC, BBR)       │ No
// Header size        │ 20 bytes (min)         │ 8 bytes
// Latency            │ Higher (handshake +ack)│ Lower
// Use cases          │ HTTP, SSH, DB, FTP     │ DNS, video, games

// ── Port number ranges ────────────────────────────────────────
const PORT_RANGES = {
  wellKnown:   { range: '0-1023',       examples: 'HTTP=80, HTTPS=443, SSH=22, DNS=53' },
  registered:  { range: '1024-49151',   examples: 'PostgreSQL=5432, Redis=6379, MySQL=3306' },
  ephemeral:   { range: '49152-65535',  examples: 'OS-assigned source ports for clients' },
};

// ── When to choose UDP ────────────────────────────────────────
const useUDP = [
  'Real-time audio/video (VoIP, WebRTC) — stale data worse than lost data',
  'DNS queries — single small request/reply, retry at app layer',
  'Online gaming — position updates; old frames are irrelevant',
  'QUIC / HTTP3 — implements own reliability with less overhead than TCP',
  'Broadcast / multicast — TCP is point-to-point only',
];

